const f = $input.first().json;
const cfg = $('Config - Turnos').first().json;
const t = v => (v ?? '').toString().trim();
const errores = [];

const nombreCompletoInput = t(f['Nombre Completo'] || f['Nombre completo']).replace(/\s+/g, ' ');
const partesNombre = nombreCompletoInput.split(' ').filter(Boolean);
const apellido = partesNombre.length > 1 ? partesNombre[partesNombre.length - 1] : '';
const nombre = partesNombre.length > 1 ? partesNombre.slice(0, -1).join(' ') : (partesNombre[0] || '');
const dni = t(f['DNI']).replace(/\D/g, '');
const email = t(f['Email']).toLowerCase();
let celular = t(f['Celular']).replace(/[\s\-()]/g, '');
if (celular && !celular.startsWith('+')) celular = '+54' + celular.replace(/^0+/, '');
const nacimiento = t(f['Fecha de nacimiento']);
const domicilio = t(f['Domicilio']);
const fecha = t(f['Fecha del turno']);
const hora = t(f['Horario']);
const motivo = t(f['Motivo de consulta']) || 'Sin motivo indicado';
const especialidad = t(f['Especialidad'] || f.especialidad);
const chat_id = t(f.chat_id) || t(cfg.chat_id_prueba).replace('PEGA_AQUI_TU_CHAT_ID','');

if (!nombreCompletoInput) errores.push('Falta el nombre completo');
else if (partesNombre.length < 2) errores.push('Ingresá nombre y apellido');
if (!/^\d{7,8}$/.test(dni)) errores.push('DNI inválido (7 u 8 números)');
if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) errores.push('Email inválido');
if (!/^\+\d{10,15}$/.test(celular)) errores.push('Celular inválido (formato internacional +54...)');
if (!domicilio) errores.push('Falta el domicilio');
if (!['Clínica Médica', 'Pediatría', 'Odontología'].includes(especialidad)) errores.push('Elegí una especialidad');
if (!chat_id) errores.push('Falta el chat de Telegram (abrí el formulario desde el bot o cargá chat_id_prueba en Config - Turnos)');

let edad = null;
const nac = new Date(nacimiento + 'T12:00:00Z');
if (isNaN(nac)) { errores.push('Fecha de nacimiento inválida'); }
else {
  const hoy = new Date();
  edad = hoy.getUTCFullYear() - nac.getUTCFullYear();
  const m = hoy.getUTCMonth() - nac.getUTCMonth();
  if (m < 0 || (m === 0 && hoy.getUTCDate() < nac.getUTCDate())) edad--;
  if (edad < 0 || edad > 120) errores.push('Fecha de nacimiento fuera de rango');
}

let inicio = null, fin = null;
const ini = new Date(`${fecha}T${hora}:00${cfg.zona_horaria}`);
if (isNaN(ini)) { errores.push('Fecha u horario del turno inválidos'); }
else {
  if (ini.getTime() <= Date.now()) errores.push('El turno debe ser a futuro');
  const dow = new Date(`${fecha}T12:00:00${cfg.zona_horaria}`).getUTCDay();
  if (dow === 0 || dow === 6) errores.push('El consultorio atiende de lunes a viernes');
  inicio = ini.toISOString();
  fin = new Date(ini.getTime() + cfg.duracion_min * 60000).toISOString();
}

return [{ json: {
  valido: errores.length === 0,
  errores: errores.join(' | '),
  nombre, apellido, nombre_completo: nombreCompletoInput,
  dni, email, celular, nacimiento, edad, domicilio,
  especialidad, fecha, hora, motivo, chat_id, inicio, fin
} }];

