const j = $input.first().json;
let out = { resumen: 'Resumen no disponible (falló la IA). Revisar manualmente.', prioridad: 'Media', alerta: 'IA no disponible', ia_ok: false };
try {
  const txt = (j.choices?.[0]?.message?.content || '').replace(/```json|```/g, '').trim();
  if (txt) {
    const p = JSON.parse(txt);
    out = {
      resumen: String(p.resumen || '').slice(0, 500),
      prioridad: ['Alta', 'Media', 'Baja'].includes(p.prioridad) ? p.prioridad : 'Media',
      alerta: String(p.alerta || ''),
      ia_ok: true
    };
  }
} catch (e) { out.alerta = 'Respuesta de IA no interpretable'; }
return [{ json: out }];

