const v = $('Validar y Normalizar Datos').first().json;
const ini = new Date(v.inicio);
const fin = new Date(v.fin);
const eventos = $input.all().map(i => i.json).filter(e =>
  e.id && e.status !== 'cancelled' && e.transparency !== 'transparent' && (!e.eventType || e.eventType === 'default'));
const choque = eventos.find(e => {
  const s = new Date(e.start?.dateTime || e.start?.date);
  const en = new Date(e.end?.dateTime || e.end?.date);
  return en > ini && s < fin;
});
const desc = choque
  ? `${choque.summary || 'evento sin título'} (${choque.start?.dateTime || choque.start?.date} → ${choque.end?.dateTime || choque.end?.date})`
  : '';
return [{ json: { libre: !choque, conflicto: desc, consultado: `${v.inicio} → ${v.fin}`, eventos_encontrados: eventos.length } }];
